import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except ValueError:
        return

    grid = []
    for i in range(n):
        row_chars = []
        for j in range(n):
            if (i + j) % 2 == 0:
                row_chars.append('W')
            else:
                row_chars.append('B')
        grid.append("".join(row_chars))

    for row in grid:
        print(row)

if __name__ == "__main__":
    solve()
